!function disconnectUsersPage(){"use strict";document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("disconnectUsersForm");if(!e)return;const t=document.getElementById("disconnectUsersTarget"),n=document.getElementById("disconnectUsersSubmit"),o=document.getElementById("disconnectUsersStatus");e.addEventListener("submit",async s=>{s.preventDefault();const i=t.selectedOptions[0];if(!t.value||!i)return;const c=`Θέλετε να αποσυνδέσετε τον χρήστη ${i.dataset.name||i.textContent.trim()} από όλες τις ενεργές συνεδρίες;`;if(window.Swal?(await window.Swal.fire({title:"Επιβεβαίωση αποσύνδεσης",text:c,icon:"warning",showCancelButton:!0,confirmButtonText:"Αποσύνδεση",cancelButtonText:"Ακύρωση"})).isConfirmed:window.confirm(c)){n.disabled=!0;try{const n=await fetch("/admin/disconnect-users",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json","X-CSRF-Token":e.querySelector('[name="_csrf"]').value},body:JSON.stringify({userId:t.value})}),s=await n.json();if(!n.ok||!0!==s.success)throw new Error("Force logout failed");o.textContent=s.message,window.Swal&&await window.Swal.fire("Επιτυχία",s.message,"success"),window.location.reload()}catch(e){console.error("[disconnect-users] Request failed:",e),o.textContent="Η αποσύνδεση δεν ολοκληρώθηκε. Δοκιμάστε ξανά.",window.Swal&&await window.Swal.fire("Σφάλμα",o.textContent,"error"),n.disabled=!1}}})})}();